const $ = selector => document.querySelector(selector);
const E = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z',note:'M5 3h10l4 4v14H5z M14 3v5h5 M8 12h8 M8 16h6',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',folder:'M3 6h7l2 2h9v12H3z',plus:'M12 5v14 M5 12h14',back:'M19 12H5 M11 6l-6 6 6 6',arrow:'M5 12h14 M13 6l6 6-6 6',close:'M6 6l12 12 M18 6 6 18',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h1 M3 12h1 M3 18h1',sliders:'M5 3v8 M5 15v6 M2 11h6 M12 3v3 M12 10v11 M9 6h6 M19 3v12 M19 19v2 M16 15h6',mark:'M7 3h10v18l-5-4-5 4z',chat:'M4 4h16v12H9l-5 4z M8 8h8 M8 12h5',more:'M5 12h.01 M12 12h.01 M19 12h.01',trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',upload:'M12 16V3 M7 8l5-5 5 5 M4 16v5h16v-5',link:'M10 14l4-4 M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 M16 8l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',pen:'M4 17l-1 4 4-1L20 7l-4-4z M13 6l5 5',crop:'M6 3v15h15 M3 6h15v15',check:'M5 12l4 4L19 6',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',download:'M12 3v13 M7 11l5 5 5-5 M4 18v3h16v-3',external:'M14 3h7v7 M21 3l-11 11 M10 5H3v16h16v-7'};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.note}"/></svg>`;
const button = (action,label,name='more',extra='') => { const cls=extra.match(/class="([^"]+)"/)?.[1]||'icon'; return `<button class="${cls}" data-action="${action}" aria-label="${E(label)}" data-tooltip="${E(label)}" ${extra.replace(/class="[^"]+"/,'')}>${icon(name)}</button>`; };
const key='reader-product-design-v1',draftKey=key+'-drafts';
const quote='当我们能用自己的话解释一个观点，并把它放进新的情境里，阅读才开始成为自己的经验。';
const books=[{id:'slow',title:'慢读的方法',author:'Reader 原创示例',format:'EPUB',color:'',folder:'学习方法',chapter:'第二章 把阅读变成理解',progress:38},{id:'attention',title:'注意力与学习',author:'Reader 原创示例',format:'PDF',color:'blue',folder:'学习方法',chapter:'第 12 页',progress:50},{id:'city',title:'城市观察手记',author:'Reader 原创示例',format:'TXT',color:'orange',folder:'随手记录',chapter:'第一章 街角',progress:12}];
const seed=()=>({folders:['学习方法','随手记录'],books:structuredClone(books),notes:[{id:'n1',title:'主动回忆为什么有效',body:'理解的证据，是我能否离开原文重新说清楚。\n\n熟悉感来自反复遇见，理解则需要主动组织。我可以在读完一小节后合上书，写下一个问题和一个例子。\n\n下次阅读时试一试\n• 先回忆，再核对原文。\n• 把不确定的地方变成具体问题。\n• 找一个生活里的例子。',folder:'学习方法',sources:[{book:'慢读的方法',bookId:'slow',location:'第二章 · 第 3 段',anchor:'p3',quote}],updated:'刚刚'},{id:'n2',title:'让注意力有一个落点',body:'把手机放远一点，给每次阅读留一个小目标。\n\n今天先试着回答一个问题：什么会打断我的理解？',folder:'随手记录',sources:[],updated:'昨天'}],annotations:[{id:'a1',bookId:'slow',anchor:'p3',quote,comment:'理解需要一次主动表达，可以把它变成每章结束后的练习。',location:'第二章 · 第 3 段'},{id:'a2',bookId:'slow',anchor:'p5',quote:'一个暂时没有答案的问题，也是一种有价值的阅读记录。',comment:'允许问题先留下来。',location:'第二章 · 第 5 段'}]});
let data;try{data=JSON.parse(localStorage.getItem(key))||seed();}catch{data=seed();}
const q=new URLSearchParams(location.search);
const state={view:q.get('view')||'library',condition:q.get('condition')||'normal',theme:q.get('theme')||'light',bookId:q.get('view')==='pdf'?'attention':'slow',noteId:'n1',tab:'annotations',panel:innerWidth>950,toc:innerWidth>1100,folder:'',filter:'all',query:'',selection:null,backToNote:null,noteList:false,saving:'saved',crop:false,pdfPage:12,chapter:2};
try{const drafts=JSON.parse(localStorage.getItem(draftKey)||'{}');for(const n of data.notes)if(drafts[n.id]){Object.assign(n,drafts[n.id]);state.saving='error';}}catch{}
let toastTimer,saveTimer,undo; const editorViews=new Map();
function emit(type,extra={}){if(parent!==window)parent.postMessage({channel:'reader-design-lab',type,...extra},location.origin);}
function event(message){emit('event',{message});}
function persist(){try{localStorage.setItem(key,JSON.stringify(data));return true;}catch{return false;}}
function toast(text,undoAction){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;if(undoAction){undo=undoAction;const b=document.createElement('button');b.textContent='撤销';b.onclick=()=>{undo?.();undo=undefined;el.hidden=true;};el.append(b);}el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,4200);}
function currentBook(){return data.books.find(b=>b.id===state.bookId)||data.books[0];}
function currentNote(){return data.notes.find(n=>n.id===state.noteId&&!n.trashed)||data.notes.find(n=>!n.trashed);}
function hideSelection(){state.selection=null;$('#selection-bar').hidden=true;window.getSelection()?.removeAllRanges();}
function navigate(view){if(state.view==='notes')saveNote();hideSelection();state.view=view;state.noteList=false;if(view==='pdf')state.bookId='attention';if(view==='reader'&&currentBook()?.format==='PDF')state.bookId='slow';render();}
function rememberEditor(){const n=currentNote(),body=$('#note-body');if(n&&body)editorViews.set(n.id,{start:body.selectionStart,end:body.selectionEnd,scroll:$('.editor-body').scrollTop,textScroll:body.scrollTop});}
function openBook(id,source){if(state.view==='notes'){rememberEditor();saveNote();}state.pdfHighlight=source?.rect;if(source?.page)state.pdfPage=source.page;state.bookId=id;state.view=currentBook().format==='PDF'?'pdf':'reader';state.chapter=2;hideSelection();render();if(source)setTimeout(()=>jump(source.anchor),50);event('打开书籍：'+currentBook().title);}
function jump(anchor){const target=document.getElementById(anchor)||document.querySelector('.pdf-page');target?.scrollIntoView({block:'center',behavior:'smooth'});target?.classList.add('pulse');setTimeout(()=>target?.classList.remove('pulse'),2200);}
function cover(book){return `<div class="cover ${book.color}"><strong>${E(book.title)}</strong><small>READER EDITIONS</small></div>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="主导航"><button data-action="library" class="${state.view==='library'?'active':''}">书库</button><button data-action="notes" class="${state.view==='notes'?'active':''}">笔记</button><button data-action="search" class="${state.view==='search'?'active':''}">搜索</button><button data-action="folders">文件夹</button></nav>`;}
function sidebar(){return `<nav class="sidebar" aria-label="主导航"><button data-action="library" class="${state.view==='library'?'active':''}">${icon('book')}书库<small>${data.books.filter(b=>!b.trashed).length}</small></button><button data-action="notes" class="${state.view==='notes'?'active':''}">${icon('note')}笔记<small>${data.notes.filter(n=>!n.trashed).length}</small></button><button data-action="search" class="${state.view==='search'?'active':''}">${icon('search')}搜索</button><div class="folder-heading">文件夹 ${button('new-folder','新建文件夹','plus')}</div>${data.folders.map(f=>`<button data-action="folder" data-folder="${E(f)}" class="${state.folder===f?'active':''}">${icon('folder')}${E(f)}</button>`).join('')}<div class="bottom"><button data-action="trash">${icon('trash')}回收站</button><button data-action="appearance">${icon('sliders')}阅读偏好</button></div></nav>`;}
function banner(){if(state.condition==='offline')return '<div class="notice"><span>当前离线 · 本地书籍和笔记仍可使用</span></div>';if(state.condition==='save-error'&&state.view!=='notes')return '<div class="notice error"><span>上次修改尚未保存，内容仍在当前页面。</span><button data-action="retry-save">重试保存</button></div>';return '';}
function noteCard(n){return `<button class="note-card" data-action="note-open" data-id="${n.id}"><small>${icon('note')} ${E(n.folder||'未分类')} · ${n.updated}</small><h3>${E(n.title||'未命名笔记')}</h3><p>${E(n.body)}</p></button>`;}
function library(){const list=state.condition==='empty'?[]:data.books.filter(b=>!b.trashed&&(!state.folder||b.folder===state.folder)&&(state.filter==='all'||b.format===state.filter));return `<div class="shell">${sidebar()}<main class="content">${mobileNav()}<header class="page-head"><div><h1>${E(state.folder||'书库')}</h1></div><div class="actions">${state.folder?button('folder-settings','管理当前文件夹','more'):button('search','搜索书籍和笔记','search')}<button class="primary" data-action="import">${icon('plus')}添加书籍</button></div></header>${!list.length?`<div class="empty">${icon('book')}<h2>${state.condition==='empty'?'从一本书开始':'这里还没有书籍'}</h2><button class="primary" data-action="import">${icon('upload')}导入第一本书</button><button class="quiet" data-action="new-note">先写一篇笔记 ${icon('arrow')}</button></div>`:`<section class="featured" aria-label="继续阅读">${cover(list[0])}<div class="featured-info"><span class="eyebrow">继续阅读</span><h2 class="serif">${E(list[0].title)}</h2><p>${E(list[0].chapter)}<br>上次读到 ${list[0].progress}% · ${E(list[0].format)}</p><div class="reading-progress"><i style="width:${list[0].progress}%"></i></div><div class="row"><button class="primary" data-action="book-open" data-id="${list[0].id}">接着读 ${icon('arrow')}</button><button class="quiet" data-action="notes">查看阅读笔记</button></div></div><div class="featured-aside"><span class="eyebrow">上次留下的想法</span><blockquote>理解的证据，是我能否离开原文重新说清楚。</blockquote><small>来自「主动回忆为什么有效」</small><button class="quiet" data-action="note-open" data-id="n1">继续写 ${icon('arrow')}</button></div></section><div class="section-head"><h2>${state.folder?'文件夹中的书籍':'全部书籍'} <small>${list.length}</small></h2><div class="filters">${['all','EPUB','PDF','TXT'].map(f=>`<button class="chip ${state.filter===f?'active':''}" data-action="filter" data-filter="${f}">${f==='all'?'全部':f}</button>`).join('')}</div></div><section class="grid">${list.map(b=>`<article class="book-card"><button class="open-book" data-action="book-open" data-id="${b.id}" aria-label="打开 ${E(b.title)}">${cover(b)}</button><div class="book-info"><button class="open-book" data-action="book-open" data-id="${b.id}"><h3>${E(b.title)}</h3></button><p>${E(b.author)}</p><p>读到 ${b.progress}% · ${data.notes.filter(n=>!n.trashed&&n.sources.some(s=>s.bookId===b.id)).length} 篇笔记</p><span class="badge">${b.format}</span></div>${button('book-menu','管理 '+b.title,'more',`data-id="${b.id}" class="icon more"`)}</article>`).join('')}</section>`}<div class="section-head"><h2>最近的笔记</h2><button class="quiet" data-action="notes">全部笔记 ${icon('arrow')}</button></div><div class="recent-notes">${(state.condition==='empty'?[]:data.notes.filter(n=>!n.trashed).slice(0,2)).map(noteCard).join('')||'<p class="muted">暂无笔记</p>'}</div></main></div>`;}
const paragraphs=[['p1','读完一页之后，我们常常觉得自己已经理解了。熟悉的词语、流畅的句子和轻轻点头的时刻，会让阅读显得毫不费力。'],['p2','但当我们合上书，试着向另一个人解释刚才读到的内容，那个清晰的印象有时就变得模糊。我们记住了作者的声音，却还没有形成自己的表达。'],['p3',quote],['p4','所以，慢读并不是每个字都读得更慢。它更像是在重要的地方停一下：这句话在回答什么问题？我是否同意？它和我已经知道的事情有什么关系？'],['p5','一个暂时没有答案的问题，也是一种有价值的阅读记录。我们不必立即整理出漂亮的结论，可以先保留疑问，等下一次阅读把它连接起来。'],['p6','试着合上书，用三句话写下这一节的意思。接着找一个生活中的例子，再回到原文，看看自己的表达省略了什么，又补充了什么。']];
function article(){if(state.bookId==='city')return `<article class="article"><div class="chapter-label">城市观察手记 / 第一章</div><h1>街角的一小段时间</h1><p id="p1">雨停后，书店门前多了一片水光。有人把伞靠在墙边，站着读完了一页书。</p><p id="p3">城市里的安静，常常藏在那些不必赶路的时刻。</p><p>我把这个句子记下来，也记下路过时闻到的面包香气。</p></article>`;return `<article class="article"><div class="chapter-label">慢读的方法 <span>／</span> 第 ${state.chapter} 章</div><h1>${state.chapter===2?'把阅读变成理解':state.chapter===1?'给阅读留一点空白':'让问题继续生长'}</h1><p class="lead">读过的文字，如何成为自己的经验？</p>${paragraphs.map(([id,text],i)=>{const marks=data.annotations.filter(a=>a.bookId===state.bookId&&a.anchor===id);let html=E(text);for(const mark of marks){if(html.includes(E(mark.quote)))html=html.replace(E(mark.quote),`<mark data-action="annotation-open" data-id="${mark.id}">${E(mark.quote)}</mark>`);}return `${i===4?'<h2>给问题留一个位置</h2>':''}<p id="${id}" data-paragraph="${id}">${html}${marks.length?`<button class="margin-number" data-action="annotation-open" data-id="${marks[0].id}" aria-label="查看此段批注">${marks.length}</button>`:''}</p>`;}).join('')}<blockquote>阅读留下的，不只是答案，还有更好的问题。</blockquote><button class="quiet" data-action="next-chapter">下一章 · 让问题继续生长 ${icon('arrow')}</button></article>`;}
function study(){const marks=data.annotations.filter(a=>a.bookId===state.bookId),notes=data.notes.filter(n=>!n.trashed&&(n.relatedBook===state.bookId||n.sources.some(s=>s.bookId===state.bookId)));return `<aside class="study" aria-label="学习面板"><div class="panel-head"><h2>随书记录</h2>${button('toggle-panel','关闭学习面板','close')}</div><div class="tabs"><button data-action="tab" data-tab="annotations" class="${state.tab==='annotations'?'active':''}">批注 ${marks.length}</button><button data-action="tab" data-tab="notes" class="${state.tab==='notes'?'active':''}">笔记 ${notes.length}</button></div>${state.tab==='annotations'?marks.map(a=>`<button class="annotation-card" data-action="annotation-open" data-id="${a.id}"><div class="annotation-meta"><small><i class="tag-dot"></i>${E(a.location)}</small><small>今天</small></div><blockquote>${E(a.quote)}</blockquote>${a.comment?`<p>${E(a.comment)}</p>`:''}</button>`).join('')||'<p class="muted">暂无批注</p>':notes.map(noteCard).join('')||'<p class="muted">暂无笔记</p>'}<div class="panel-bottom">${button('new-note','新建阅读笔记','plus')}</div></aside>`;}
function reader(){const b=currentBook(),isPdf=state.view==='pdf';return `${state.backToNote?'<div class="back-note"><button data-action="back-note">← 返回刚才的笔记</button></div>':''}<header class="reader-top">${button('library','返回书库','back')}<div class="reader-title">${E(b.title)}<small>${b.format} · ${E(b.folder)}</small></div><div class="reader-tools">${button('toggle-toc','目录','list')}${button('book-search','搜索本书','search','class="icon desktop-only"')}${button('appearance','阅读外观','sliders','class="icon desktop-only"')}<span class="divider"></span>${button('bookmark','收藏当前位置','mark','class="icon desktop-only"')}${button('chat-open','打开阅读对话','chat')}${button('toggle-panel','批注与笔记','note')}${button('reader-more','更多阅读操作','more','class="icon mobile-only"')}</div></header><div class="reader-layout">${state.toc?`<aside class="toc" aria-label="目录">${button('toggle-toc','关闭目录','close','class="icon drawer-close"')}<h2>目录</h2>${(isPdf?['注意力的边界','从输入到主动回忆','图表与练习','延伸阅读']:['给阅读留一点空白','把阅读变成理解','让问题继续生长','连接新的经验']).map((x,i)=>`<button data-action="chapter" data-index="${i+1}" class="${state.chapter===i+1?'active':''}"><span>0${i+1}</span>${x}</button>`).join('')}</aside>`:''}${isPdf?`<main class="pdf-scroll"><div class="pdf-hint"><span>${state.crop?'框选区域 · Esc 取消':'第 '+state.pdfPage+' 页'}</span>${button('crop',state.crop?'取消框选':'框选区域','crop')}</div><div class="pdf-page ${state.crop?'selecting':''}"><canvas id="pdf-canvas" width="1120" height="1440" aria-label="原创 PDF 示例页面，注意力与学习"></canvas><div class="region-box" hidden></div></div></main>`:`<main class="reading-scroll" aria-label="书籍正文" tabindex="0">${article()}</main>`}${state.panel?study():''}</div><footer class="reading-footer"><button data-action="toggle-toc">${isPdf?'注意力与学习 · 第 '+state.pdfPage+' 页':'第 '+state.chapter+' 章 · 把阅读变成理解'}</button><div>${isPdf?'<button data-action="pdf-prev" aria-label="上一页">‹</button> '+state.pdfPage+' / 24 <button data-action="pdf-next" aria-label="下一页">›</button>':'<span class="save-ok" aria-label="位置已保存" data-tooltip="位置已保存">'+icon('check')+'</span>　38%'}</div></footer>`;}
function sourceCard(source,index){const missing=state.condition==='missing-source'||data.books.find(b=>b.id===source.bookId)?.trashed;return `<div class="source-card"><div class="source-line">${icon(source.image?'crop':'link')}<span>${E(source.book)} · ${E(source.location)}</span></div>${source.image?`<img src="${source.image}" alt="保存的 PDF 区域摘录">`:''}<p>“${E(source.quote)}”</p><button data-action="source" data-source="${index}" data-anchor="${E(source.anchor)}" data-book="${source.bookId}">${missing?'来源暂不可用 · 查看恢复方式':'回到原文 ↗'}</button></div>`;}
function notesView(){const notes=state.condition==='empty'?[]:data.notes.filter(n=>!n.trashed),n=currentNote();return `<div class="shell notes-shell">${sidebar()}<div class="note-layout ${state.noteList?'list-only':''}"><aside class="note-list"><div class="list-head"><h1>笔记</h1>${button('new-note','新建笔记','plus')}</div>${mobileNav()}${notes.map(note=>`<button class="note-row ${n?.id===note.id?'active':''}" data-action="note-open" data-id="${note.id}"><h3>${E(note.title||'未命名笔记')}</h3><p>${E(note.body)}</p><small>${E(note.folder||'未分类')} · ${note.sources.length} 处来源</small></button>`).join('')}</aside>${!notes.length?`<main class="note-editor"><div class="empty">${icon('note')}<h2>让想法有一个落点</h2><button class="primary" data-action="new-note">新建第一篇笔记</button></div></main>`:`<main class="note-editor"><header class="editor-head">${button('note-list','返回笔记列表','back','class="icon mobile-only"')}<span>${E(n.folder||'未分类')}</span><span class="desktop-only">／ ${E(n.title||'未命名笔记')}</span><div class="actions">${button('space','整理到 Space','external')}${button('note-menu','笔记操作','more')}</div></header><div class="editor-body"><label class="sr-only" for="note-title">笔记标题</label><input class="title-input" id="note-title" value="${E(n.title)}" placeholder="未命名笔记"><div class="note-details"><span>今天编辑</span><span>${n.sources.length} 处原文引用</span><button class="quiet" data-action="move-note">${icon('folder')}${E(n.folder||'未分类')}</button></div><div class="editor-format" aria-label="编辑工具"><button data-action="format-bold" aria-label="加粗选中文字"><b>B</b></button><button data-action="format-heading" aria-label="插入小标题">H2</button><button data-action="format-list" aria-label="插入列表">☷</button><span class="divider-line"></span>${button('insert-source','插入来源','link')}</div>${n.sources.map(sourceCard).join('')}<label class="sr-only" for="note-body">笔记正文</label><textarea class="body-input" id="note-body" placeholder="写下你的理解，或者先留下一个问题…">${E(n.body)}</textarea></div><footer class="note-footer" id="note-save"><span>${state.saving==='error'?'修改尚未保存':state.saving==='saving'?'保存中…':'<span class="save-ok" aria-label="已保存到 Reader" data-tooltip="已保存到 Reader">'+icon('check')+'<span class="sr-only">已保存到 Reader</span></span>'}</span><span id="word-count">${n.body.length} 字</span></footer></main>`}</div></div>`;}
function searchView(){return `<div class="shell">${sidebar()}<main class="content">${mobileNav()}<h1>搜索书籍与想法</h1><div class="search-box">${icon('search')}<label class="sr-only" for="global-search">搜索书籍、批注和笔记</label><input id="global-search" placeholder="搜索书籍、批注和笔记" value="${E(state.query)}"></div><p class="muted" style="font-size:11px">本地 · 已缓存章节</p><div id="search-results">${resultsHtml()}</div></main></div>`;}
function resultsHtml(){const query=state.query.trim().toLowerCase();if(!query)return '';const results=[];for(const b of data.books.filter(b=>!b.trashed))if((b.title+b.chapter+(b.id==='slow'?paragraphs.map(x=>x[1]).join(''):'' )).toLowerCase().includes(query))results.push(`<button class="search-result" data-action="book-open" data-id="${b.id}"><small>书籍 · ${b.format}</small><h3>${E(b.title)}</h3><p>${E(b.id==='slow'?quote:b.chapter)}</p></button>`);for(const n of data.notes.filter(n=>!n.trashed))if((n.title+n.body).toLowerCase().includes(query))results.push(`<button class="search-result" data-action="note-open" data-id="${n.id}"><small>笔记 · ${E(n.folder)}</small><h3>${E(n.title)}</h3><p>${E(n.body.slice(0,110))}</p></button>`);for(const a of data.annotations)if((a.quote+a.comment).toLowerCase().includes(query))results.push(`<button class="search-result" data-action="search-annotation" data-id="${a.id}"><small>批注 · ${E(a.location)}</small><h3>${E(a.comment||'高亮')}</h3><p>${E(a.quote)}</p></button>`);return `<div class="section-head"><h2>${results.length} 条结果</h2></div>${results.join('')||'<p class="muted">没有匹配结果</p>'}`;}
function render(){const focused=document.activeElement?.dataset?.action;document.body.dataset.theme=state.theme;$('#selection-bar').hidden=true;$('#app').innerHTML=banner()+(['reader','pdf'].includes(state.view)?reader():state.view==='notes'?notesView():state.view==='search'?searchView():library());if(state.view==='pdf')drawPdf();if(state.view==='notes'){updateSaveState();const saved=editorViews.get(currentNote()?.id);if(saved&&$('#note-body')){const body=$('#note-body');body.focus({preventScroll:true});body.setSelectionRange(saved.start,saved.end);body.scrollTop=saved.textScroll;$('.editor-body').scrollTop=saved.scroll;}}else if(focused){document.querySelector(`[data-action="${focused}"]`)?.focus({preventScroll:true});}window.readerEnhance?.();}
function dialog(title,body,primary,onSubmit){const previous=document.activeElement;const el=document.createElement('dialog');el.className='dialog';el.innerHTML=`${button('dialog-close','关闭对话框','close','class="icon dialog-close"')}<h2 id="dialog-title">${E(title)}</h2><form>${body}<div class="dialog-actions"><button class="secondary" type="button" data-action="dialog-close">取消</button>${primary?`<button class="primary" type="submit">${E(primary)}</button>`:''}</div></form>`;el.setAttribute('aria-labelledby','dialog-title');$('#modal-root').replaceChildren(el);el.addEventListener('close',()=>{el.remove();if(previous?.isConnected)previous.focus();});el.querySelector('form').onsubmit=e=>{e.preventDefault();onSubmit?.(el);};el.showModal();return el;}
function closeDialog(){$('.dialog')?.close();}
function selectionContext(){return state.selection||{book:currentBook().title,bookId:state.bookId,location:state.view==='pdf'?'第 '+state.pdfPage+' 页':'第二章 · 第 3 段',anchor:'p3',quote};}
function showSelection(text,anchor,rect){state.selection={book:currentBook().title,bookId:state.bookId,location:"第 "+state.chapter+" 章 · "+(anchor==="p3"?"第 3 段":"所选段落"),anchor,quote:text};const bar=$("#selection-bar");bar.innerHTML=button("highlight","高亮","pen")+button("comment","批注","chat")+button("ask","问 Codex","spark")+button("capture-note","记笔记","note");bar.hidden=false;const w=bar.offsetWidth;bar.style.left=Math.max(6,Math.min(rect.left+rect.width/2-w/2,innerWidth-w-6))+"px";const above=rect.top-bar.offsetHeight-8,below=rect.bottom+8;bar.style.top=(above>=55?above:Math.min(below,innerHeight-bar.offsetHeight-40))+"px";}
function selectExample(){if(!['reader','pdf'].includes(state.view))openBook('slow');if(state.view==='pdf'){state.crop=true;render();return;}const target=$('#p3');if(!target)return;target.scrollIntoView({block:'center',behavior:'instant'});const range=document.createRange();range.selectNodeContents(target);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);showSelection(target.childNodes[0].textContent,'p3',range.getBoundingClientRect());}
function addAnnotation(comment=''){const source=selectionContext();const id=crypto.randomUUID();data.annotations.push({...source,id,comment});persist();state.tab='annotations';hideSelection();render();jump(source.anchor);toast(comment?'批注已保存':'已高亮所选文字',()=>{data.annotations=data.annotations.filter(a=>a.id!==id);persist();render();});event('保存批注：'+source.location);}
function ask(source=selectionContext()){window.readerChat?.open(source);hideSelection();}
function createNote(source,title='未命名笔记',body=''){const n={id:crypto.randomUUID(),title,body,folder:currentBook()?.folder||'未分类',sources:source?[structuredClone(source)]:[],relatedBook:['reader','pdf'].includes(state.view)?state.bookId:undefined,updated:'刚刚'};data.notes.unshift(n);state.noteId=n.id;state.condition=state.condition==='empty'?'normal':state.condition;state.view='notes';state.noteList=false;state.saving='saved';persist();render();setTimeout(()=>$('#note-body')?.focus(),0);event('创建笔记：'+title);return n;}
function captureNote(){const source=structuredClone(selectionContext());const choices=data.notes.filter(n=>!n.trashed);dialog('把原文加入笔记',`<div class="dialog-quote">${E(source.quote)}</div><label for="target-note">保存到</label><select id="target-note"><option value="new">新建一篇笔记</option>${choices.map(n=>`<option value="${n.id}">${E(n.title)}</option>`).join('')}</select>`,'加入笔记',()=>{const id=$('#target-note').value;closeDialog();hideSelection();if(id==='new')createNote(source,'关于'+source.book+'的一点想法');else{const n=data.notes.find(n=>n.id===id);n.sources.push(source);state.noteId=id;state.view='notes';state.saving='saved';persist();render();toast('原文引用已加入笔记');}});}
function updateSaveState(){const el=$('#note-save');if(!el)return;el.classList.toggle('error',state.saving==='error');el.innerHTML=`<span>${state.saving==='error'?'这次修改尚未保存':state.saving==='saving'?'保存中…':'<span class="save-ok" aria-label="已保存到 Reader" data-tooltip="已保存到 Reader">'+icon('check')+'<span class="sr-only">已保存到 Reader</span></span>'}${state.saving==='error'?' <button data-action="retry-save">重试保存</button>':''}</span><span>${currentNote()?.body.length||0} 字</span>`;}
function saveNote(){clearTimeout(saveTimer);if(state.saving==='saved')return;if(state.condition==='save-error'||!persist()){state.saving='error';}else{state.saving='saved';try{localStorage.removeItem(draftKey);}catch{}event('笔记内容已保存到原型存储');}updateSaveState();}
function editNote(){const n=currentNote();if(!n)return;n.title=$('#note-title').value;n.body=$('#note-body').value;n.updated='刚刚';state.saving='saving';try{const drafts=JSON.parse(localStorage.getItem(draftKey)||'{}');drafts[n.id]={title:n.title,body:n.body};localStorage.setItem(draftKey,JSON.stringify(drafts));}catch{}updateSaveState();clearTimeout(saveTimer);saveTimer=setTimeout(saveNote,600);}
function moveItem(item){dialog('移动到文件夹',`<label for="move-target">${E(item.title)} 的归属位置</label><select id="move-target"><option>未分类</option>${data.folders.map(f=>`<option ${f===item.folder?'selected':''}>${E(f)}</option>`).join('')}</select>`,'移动',()=>{const old=item.folder;item.folder=$('#move-target').value;closeDialog();persist();render();toast('已移动到「'+item.folder+'」',()=>{item.folder=old;persist();render();});});}
function exportNote(){const n=currentNote();const text='# '+n.title+'\n\n'+n.body+'\n\n'+n.sources.map(s=>'> '+s.quote+'\n\n来源：'+s.book+' · '+s.location).join('\n\n');const blob=new Blob([text],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=(n.title||'笔记').replace(/[\\/:*?"<>|]/g,'-')+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('笔记已导出为 Markdown');}
const actions={
 library(){state.folder='';state.filter='all';state.backToNote=null;navigate('library');},notes(){navigate('notes');},search(){navigate('search');},'book-open':el=>openBook(el.dataset.id),'note-open':el=>{state.noteId=el.dataset.id;state.condition=state.condition==='empty'?'normal':state.condition;navigate('notes');},
 folder:el=>{state.folder=el.dataset.folder;state.filter='all';navigate('library');},filter:el=>{state.filter=el.dataset.filter;render();},
 'new-folder'(){dialog('新建文件夹','<label for="folder-name">文件夹名称</label><input id="folder-name" maxlength="40" placeholder="例如：认知与学习" required>','创建',()=>{const name=$('#folder-name').value.trim();if(!name||data.folders.includes(name)){toast('请填写一个尚未使用的文件夹名称');return;}data.folders.push(name);persist();closeDialog();render();toast('文件夹已创建');});},
 folders(){dialog('文件夹',data.folders.map(f=>`<button class="option-row" data-action="folder-dialog" data-folder="${E(f)}" type="button">${icon('folder')}${E(f)}</button>`).join('')+'<button class="quiet" data-action="new-folder" type="button">＋ 新建文件夹</button>');},
 'folder-dialog':el=>{closeDialog();state.folder=el.dataset.folder;navigate('library');},
 'folder-settings'(){const old=state.folder;dialog('管理文件夹',`<label for="folder-name">名称</label><input id="folder-name" value="${E(old)}" maxlength="40" required>`,'保存名称',()=>{const name=$('#folder-name').value.trim();if(!name||name!==old&&data.folders.includes(name)){toast('名称不能为空或与现有文件夹重复');return;}data.folders=data.folders.map(f=>f===old?name:f);for(const item of [...data.books,...data.notes])if(item.folder===old)item.folder=name;state.folder=name;persist();closeDialog();render();toast('文件夹已重命名，引用保持不变');});},
 'new-note'(){createNote(null,'');},'toggle-panel'(){state.panel=!state.panel;render();},'toggle-toc'(){state.toc=!state.toc;render();},tab:el=>{state.tab=el.dataset.tab;render();},'select-example':selectExample,highlight:()=>addAnnotation(),
 comment(){const source=selectionContext();dialog('为这段原文写批注',`<div class="dialog-quote">${E(source.quote)}</div><label for="comment-text">我的想法</label><textarea id="comment-text" placeholder="写下理解，也可以先留下一个问题…" required></textarea>`,'保存批注',()=>{const comment=$('#comment-text').value.trim();if(!comment)return;closeDialog();addAnnotation(comment);});},
 'annotation-open':el=>{const a=data.annotations.find(a=>a.id===el.dataset.id);state.selection={...a,book:currentBook().title};if(innerWidth<951){state.panel=false;render();}jump(a.anchor);dialog('原文批注',`<small>${E(a.location)}</small><div class="dialog-quote">${E(a.quote)}</div><label for="comment-text">我的想法</label><textarea id="comment-text">${E(a.comment)}</textarea><button class="quiet" type="button" data-action="annotation-note" data-id="${a.id}">加入笔记 →</button>`,'保存修改',()=>{a.comment=$('#comment-text').value;closeDialog();persist();render();jump(a.anchor);toast('批注已更新');});},
 'annotation-note':el=>{const a=data.annotations.find(x=>x.id===el.dataset.id);closeDialog();state.selection={...a,book:currentBook().title};captureNote();},ask:()=>ask(),'capture-note':captureNote,
 'search-annotation':el=>{const a=data.annotations.find(x=>x.id===el.dataset.id);openBook(a.bookId,a);},
 source:el=>{if(state.condition==='missing-source'||data.books.find(b=>b.id===el.dataset.book)?.trashed){dialog('原文暂时不可用','<p>这张引用卡中的摘录仍然保留。示例来源已被移入回收站，恢复后可以重新跳转。</p>','恢复示例来源',()=>{state.condition='normal';const book=data.books.find(b=>b.id===el.dataset.book);if(book)book.trashed=false;persist();closeDialog();render();toast('来源已恢复');});return;}state.backToNote=state.noteId;openBook(el.dataset.book,currentNote()?.sources[Number(el.dataset.source)]||{anchor:el.dataset.anchor});},
 'back-note'(){state.noteId=state.backToNote||state.noteId;state.backToNote=null;navigate('notes');},'note-list'(){state.noteList=true;render();},'move-note':()=>moveItem(currentNote()),
 'retry-save'(){state.condition='normal';state.saving='saving';saveNote();render();toast('修改已保存');},
 'format-bold'(){format('**','**');},'format-heading'(){format('\n## ','');},'format-list'(){format('\n- ','');},
 'insert-source'(){dialog('插入原文引用','<p>从书中选择一段文字，或在 PDF 中框选区域，然后点击「记笔记」并选择当前笔记。</p>','打开慢读的方法',()=>{closeDialog();state.backToNote=state.noteId;openBook('slow');});},
 'note-menu'(){dialog('笔记操作','<button class="option-row" type="button" data-action="move-current-note">移动到文件夹</button><button class="option-row" type="button" data-action="export-note">导出 Markdown</button><button class="option-row" type="button" data-action="trash-note">移到回收站</button>');},
 'move-current-note'(){closeDialog();moveItem(currentNote());},'export-note'(){closeDialog();exportNote();},
 'trash-note'(){const n=currentNote();closeDialog();n.trashed=true;persist();state.noteId=data.notes.find(x=>!x.trashed)?.id;render();toast('笔记已移到回收站',()=>{n.trashed=false;persist();state.noteId=n.id;render();});},
 'book-menu':el=>{const b=data.books.find(x=>x.id===el.dataset.id);dialog(b.title,`<button class="option-row" type="button" data-action="move-book" data-id="${b.id}">移动到文件夹</button><button class="option-row" type="button" data-action="trash-book" data-id="${b.id}">移到回收站</button>`);},
 'move-book':el=>{const b=data.books.find(x=>x.id===el.dataset.id);closeDialog();moveItem(b);},'trash-book':el=>{const b=data.books.find(x=>x.id===el.dataset.id);b.trashed=true;closeDialog();persist();render();toast('书籍已移到回收站，引用摘录保留',()=>{b.trashed=false;persist();render();});},
 trash(){const items=[...data.books,...data.notes].filter(x=>x.trashed);dialog('回收站',items.length?items.map(x=>`<div class="option-row"><span>${E(x.title)}<br><small>原文和相关记录仍被保留</small></span><button type="button" class="quiet" data-action="restore" data-id="${x.id}">恢复</button></div>`).join(''):'<p>回收站是空的。移除的书籍和笔记可以在这里恢复。</p>');},
 restore:el=>{const item=[...data.books,...data.notes].find(x=>x.id===el.dataset.id);item.trashed=false;persist();closeDialog();render();toast('已恢复「'+item.title+'」');},
 import(){dialog('添加书籍','<p>导入 TXT、EPUB 或 PDF。相同文件保留已有进度和笔记。</p><div class="file-drop">'+icon('upload')+'<p>将文件拖到这里，或选择文件</p><button type="button" data-action="demo-import">使用原创示例体验导入</button><small>设计原型不读取本机书籍</small></div><button type="button" class="quiet" data-action="online-demo">从在线书源找书 →</button>');},
 'demo-import'(){closeDialog();state.condition='normal';state.folder='';state.filter='all';if(data.books.find(b=>b.id==='attention'&&!b.trashed)){toast('示例已在书库中，保留已有进度和笔记');}else{data.books=data.books.filter(b=>b.id!=='attention');data.books.push(structuredClone(books[1]));persist();toast('注意力与学习已导入');}state.view='library';render();},
 'online-demo'(){closeDialog();dialog('从书源找书','<p>现有在线找书功能保留在这里：搜索 → 查看详情 → 开始阅读。书源管理从此页的设置入口进入。</p><p>本原型不访问外部书源。</p>','返回书库',()=>{closeDialog();navigate('library');});},
 appearance(){dialog('阅读外观',`<p>沿用当前 Reader 的安静配色。深色用于低光环境，正文保留独立字号。</p><div class="row"><button type="button" class="secondary" data-action="theme-light">浅色</button><button type="button" class="secondary" data-action="theme-dark">深色</button></div>`,'完成',closeDialog);},'theme-light'(){state.theme='light';document.body.dataset.theme='light';},'theme-dark'(){state.theme='dark';document.body.dataset.theme='dark';},
 bookmark(){toast('已收藏当前位置',()=>toast('已取消收藏'));},
 chapter:el=>{state.chapter=Number(el.dataset.index);if(state.view==='pdf')state.pdfPage=[1,12,18,23][state.chapter-1];state.toc=innerWidth>950;render();event('切换到第 '+state.chapter+' 章');},'next-chapter'(){state.chapter=Math.min(4,state.chapter+1);render();},
 'book-search'(){const book=currentBook();state.query=book.id==='slow'?'理解':book.title;navigate('search');},
 'reader-more'(){dialog('阅读操作',`<button class="option-row" type="button" data-action="more-search">搜索本书</button><button class="option-row" type="button" data-action="appearance">阅读外观</button><button class="option-row" type="button" data-action="bookmark">收藏当前位置</button>`);},'more-search'(){closeDialog();actions['book-search']();},
 crop(){state.crop=!state.crop;render();},'pdf-next'(){state.pdfPage=Math.min(24,state.pdfPage+1);render();},'pdf-prev'(){state.pdfPage=Math.max(1,state.pdfPage-1);render();},
 space(){const n=currentNote();dialog('整理到 Space',`<p>将这篇笔记的正文与 ${n.sources.length} 处来源交给 Codex，整理为一篇 Page。原笔记继续保存在 Reader。</p><label for="space-target">目标</label><select id="space-target"><option>新建私人 Page</option><option>在对话中指定已有 Page</option></select><p>原型仅预览交接内容，不访问 Space，也不显示虚假的完成链接。</p>`,'查看交接内容',()=>{closeDialog();dialog('交给 Codex 的整理请求',`<textarea readonly>请把 Reader 笔记《${E(n.title)}》整理到 Space，保留原文引用，完成后返回 Page 链接。</textarea><p>真实产品将在收到 Page 写入成功回执后显示「已整理」。</p>`,'完成预览',closeDialog);});},
 'dialog-close':closeDialog
};
function format(before,after){const el=$('#note-body');if(!el)return;const start=el.selectionStart,end=el.selectionEnd;el.setRangeText(before+el.value.slice(start,end)+after,start,end,'select');el.focus();editNote();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();actions[el.dataset.action]?.(el);});
document.addEventListener('input',e=>{if(['note-title','note-body'].includes(e.target.id))editNote();if(e.target.id==='global-search'){state.query=e.target.value;$('#search-results').innerHTML=resultsHtml();}});
function readSelection(){if(state.view!=='reader'||$('.dialog'))return;const s=window.getSelection();if(!s||s.isCollapsed||!s.rangeCount)return;const range=s.getRangeAt(0),node=range.commonAncestorContainer.nodeType===1?range.commonAncestorContainer:range.commonAncestorContainer.parentElement;const article=node.closest?.('.article');if(!article)return;const text=s.toString().trim();if(text.length<2)return;const anchor=(range.startContainer.nodeType===1?range.startContainer:range.startContainer.parentElement).closest?.('[data-paragraph],p[id]')?.id||'p3';showSelection(text,anchor,range.getBoundingClientRect());}
document.addEventListener('mouseup',e=>{if(!e.target.closest?.('#selection-bar'))setTimeout(readSelection,20);});
document.addEventListener('keyup',e=>{if(e.shiftKey)readSelection();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideSelection();if(state.crop){state.crop=false;render();}else if(!$('.dialog')&&innerWidth<951&&(state.panel||state.toc)){state.panel=false;state.toc=false;render();}}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();saveNote();}});
window.addEventListener('message',e=>{if(e.source!==parent||e.origin!==location.origin||e.data?.channel!=='reader-design-lab')return;const m=e.data;if(m.type==='reset'){data=seed();localStorage.removeItem(draftKey);persist();state.condition='normal';state.folder='';state.noteId='n1';state.saving='saved';render();toast('原创示例已重置');}else if(m.type==='select-example')selectExample();else if(m.type==='save-answer'){createNote(m.context,m.title,m.body);toast('演示回答已保存为 Reader 笔记');}});
function drawPdf(){const canvas=$('#pdf-canvas');if(!canvas)return;const c=canvas.getContext('2d');c.scale(2,2);c.fillStyle='#fff';c.fillRect(0,0,560,720);c.fillStyle='#526b66';c.font='10px Segoe UI';c.fillText('READER RESEARCH NOTES',50,43);c.fillText('学习与认知 / 原创示意材料',50,61);c.strokeStyle='#dfe6df';c.beginPath();c.moveTo(50,78);c.lineTo(510,78);c.stroke();c.fillStyle='#253c34';c.font='25px Microsoft YaHei';c.fillText('注意力如何影响理解',50,123);c.font='11px Microsoft YaHei';c.fillStyle='#69796e';c.fillText('第二节   从信息输入到主动回忆',50,153);c.fillStyle='#42594c';c.font='12px Microsoft YaHei';const lines=['同样的一页内容，在不同的阅读方式下，会留下不同的印象。','当注意力有一个明确的问题作为落点，我们更容易组织信息，','并在阅读之后重新提取它。下面用一组示意数据呈现这种关系。'];lines.forEach((line,i)=>c.fillText(line,50,196+i*24));c.fillStyle='#f4f6ef';c.fillRect(50,275,460,245);c.fillStyle='#3e5649';c.font='12px Microsoft YaHei';c.fillText('图 2  阅读方式与回忆表现',72,304);c.fillStyle='#7e8c7e';c.font='9px Microsoft YaHei';c.fillText('示意值 · 非研究数据',361,304);for(let i=0;i<4;i++){const y=337+i*43;c.strokeStyle='#dce5d5';c.beginPath();c.moveTo(92,y);c.lineTo(476,y);c.stroke();c.fillText(String(90-i*20),66,y+3);}const values=[{x:139,h:70,label:'重复阅读',color:'#b1c3a5'},{x:258,h:112,label:'划线标记',color:'#809e83'},{x:377,h:151,label:'主动回忆',color:'#426e58'}];for(const v of values){c.fillStyle=v.color;c.fillRect(v.x,466-v.h,58,v.h);c.fillStyle='#51694f';c.font='11px Microsoft YaHei';c.fillText(v.label,v.x+4,488);}c.font='11px Microsoft YaHei';c.fillStyle='#6b7c6a';c.fillText('先回忆，再核对：把模糊的熟悉感变成可检查的理解。',50,549);c.fillStyle='#354d40';c.font='12px Microsoft YaHei';c.fillText('可以尝试的练习',50,590);c.fillStyle='#60735f';c.fillText('1. 合上书，用自己的话写下三个要点。',50,615);c.fillText('2. 回到原文，补上遗漏，并留下新的问题。',50,638);c.strokeStyle='#dfe6df';c.beginPath();c.moveTo(50,678);c.lineTo(510,678);c.stroke();c.font='10px Georgia';c.fillText(String(state.pdfPage),276,702);
let start;const page=canvas.parentElement,box=page.querySelector('.region-box');if(state.pdfHighlight){const r=state.pdfHighlight;box.hidden=false;box.style.cssText=`left:${r.x*100}%;top:${r.y*100}%;width:${r.w*100}%;height:${r.h*100}%`;}const point=e=>{const r=canvas.getBoundingClientRect();return{x:Math.max(0,Math.min(r.width,e.clientX-r.left)),y:Math.max(0,Math.min(r.height,e.clientY-r.top)),r};};canvas.addEventListener('pointerdown',e=>{if(!state.crop)return;start=point(e);canvas.setPointerCapture(e.pointerId);box.hidden=false;box.style.cssText=`left:${start.x}px;top:${start.y}px;width:0;height:0`;});canvas.addEventListener('pointermove',e=>{if(!start)return;const p=point(e);box.style.left=Math.min(start.x,p.x)+'px';box.style.top=Math.min(start.y,p.y)+'px';box.style.width=Math.abs(p.x-start.x)+'px';box.style.height=Math.abs(p.y-start.y)+'px';});canvas.addEventListener('pointerup',e=>{if(!start)return;const p=point(e),x=Math.min(start.x,p.x),y=Math.min(start.y,p.y),w=Math.abs(p.x-start.x),h=Math.abs(p.y-start.y);start=null;box.hidden=true;if(w<12||h<12){toast('请拖动框选一个更大的区域');return;}const crop=document.createElement('canvas'),scale=canvas.width/p.r.width;crop.width=Math.round(w*scale);crop.height=Math.round(h*scale);crop.getContext('2d').drawImage(canvas,x*scale,y*scale,w*scale,h*scale,0,0,crop.width,crop.height);const source={book:'注意力与学习',bookId:'attention',location:'第 '+state.pdfPage+' 页 · 区域摘录',page:state.pdfPage,anchor:'pdf-region',quote:'选中的页面区域',image:crop.toDataURL('image/png'),rect:{x:x/p.r.width,y:y/p.r.height,w:w/p.r.width,h:h/p.r.height}};state.crop=false;state.selection=source;dialog('保留这张图的出处',`<small>注意力与学习 · 第 ${state.pdfPage} 页</small><img class="crop-preview" src="${source.image}" alt="实际框选区域的预览"><button class="secondary" type="button" id="crop-ask">${icon('chat')}问 Codex</button>`,'加入笔记',()=>{closeDialog();state.selection=source;captureNote();});$('#crop-ask').onclick=()=>{closeDialog();ask(source);};event('已截取 PDF 示意页面的实际区域');});}
render();
